namespace CleanArchitecture.Blazor.Application.Features.Systems.EventHandlers;

public class SystemCreatedEventHandler : INotificationHandler<SystemCreatedEvent>
{
    private readonly ILogger<SystemCreatedEventHandler> _logger;

    public SystemCreatedEventHandler(
        ILogger<SystemCreatedEventHandler> logger
    )
    {
        _logger = logger;
    }

    public Task Handle(SystemCreatedEvent notification, CancellationToken cancellationToken)
    {
        _logger.LogInformation("System created: {SystemName} (ID: {SystemId}) by {CreatedBy} at {CreatedOn}", 
            notification.Item.Name, 
            notification.Item.Id, 
            notification.Item.CreatedBy, 
            notification.Item.Created);
        
        return Task.CompletedTask;
    }
}